-- --------------------------------------------------------- concerts

-- attended: Judas Priest @ Podilatodromio OAKA 2001-07-01
with ins as (
  insert into concerts (
    owner_id, source, source_id, status, title, event_date, start_time,
    venue, city, country, is_festival, festival_name,
    image_url, ticket_url, source_url, score, match_reason,
    rating, notes, discovered_at, planned_at, attended_at
  )
  select owner_id, 'manual', null, 'attended'::concert_status, 'Rockwave Festival 2001', '2001-07-01'::date, null,
         'Podilatodromio OAKA', 'Athens', 'GR', true, 'Rockwave Festival 2001',
         'https://www.festivalinfo.nl/img/artist/164/100_Judas_Priest_3.jpg', null, null, null, null,
         null, 'First concert ever attended', '2026-01-01T00:00:00.000Z'::timestamptz, null, '2026-01-01T00:00:00.000Z'::timestamptz
  from _ctx
  on conflict do nothing
  returning id
)
insert into concert_artists (concert_id, artist_id, role, position)
select ins.id, a.id, v.role, v.position
from ins
cross join (values ('judas priest', 'headliner', 0)) as v(name_key, role, position)
join artists a on a.name_key = v.name_key and a.owner_id = (select owner_id from _ctx)
on conflict do nothing;

-- attended: Sólstafir + Oranssi Pazuzu + Hulder @ Patronaat 2026-06-18
with ins as (
  insert into concerts (
    owner_id, source, source_id, status, title, event_date, start_time,
    venue, city, country, is_festival, festival_name,
    image_url, ticket_url, source_url, score, match_reason,
