  )
  select owner_id, 'manual', null, 'attended'::concert_status, 'Sólstafir + Oranssi Pazuzu + Hulder', '2026-06-18'::date, null,
         'Patronaat', 'Haarlem', 'NL', false, null,
         null, null, null, null, null,
         null, null, '2026-06-19T00:00:00.000Z'::timestamptz, null, '2026-06-19T00:00:00.000Z'::timestamptz
  from _ctx
  on conflict do nothing
  returning id
)
insert into concert_artists (concert_id, artist_id, role, position)
select ins.id, a.id, v.role, v.position
from ins
cross join (values ('solstafir', 'headliner', 0), ('oranssi pazuzu', 'support', 1), ('hulder', 'support', 2)) as v(name_key, role, position)
join artists a on a.name_key = v.name_key and a.owner_id = (select owner_id from _ctx)
on conflict do nothing;

