    owner_id, source, source_id, status, title, event_date, start_time,
    venue, city, country, is_festival, festival_name,
    image_url, ticket_url, source_url, score, match_reason,
    rating, notes, discovered_at, planned_at, attended_at
  )
  select owner_id, 'manual', null, 'planned'::concert_status, 'Antimatter + Sleeping Pulse', '2026-09-20'::date, null,
         'Boerderij', 'Zoetermeer', 'NL', false, null,
         null, 'https://www.podiuminfo.nl/ticket/133996/cd/Antimatter-Sleeping-Pulse/Boerderij/', null, 45, null,
         null, null, null, '2026-07-27T15:21:44.696Z'::timestamptz, null
  from _ctx
  on conflict do nothing
  returning id
)
insert into concert_artists (concert_id, artist_id, role, position)
select ins.id, a.id, v.role, v.position
from ins
cross join (values ('antimatter', 'headliner', 0), ('sleeping pulse', 'support', 1)) as v(name_key, role, position)
join artists a on a.name_key = v.name_key and a.owner_id = (select owner_id from _ctx)
on conflict do nothing;

