    rating, notes, discovered_at, planned_at, attended_at
  )
  select owner_id, 'podiuminfo', '474450', 'dismissed'::concert_status, null, '2027-04-29'::date, null,
         'Amare', 'Den Haag', 'NL', false, null,
         'https://www.festivalinfo.nl/img/artist/116/100_Hooverphonic_8.jpg', null, 'https://www.podiuminfo.nl/concert/474450/Hooverphonic/Amare/', 46, 'Known artist: Hooverphonic',
         null, null, '2026-07-27T20:52:26.545Z'::timestamptz, null, null
  from _ctx
  on conflict do nothing
  returning id
)
insert into concert_artists (concert_id, artist_id, role, position)
select ins.id, a.id, v.role, v.position
from ins
cross join (values ('hooverphonic', 'headliner', 0)) as v(name_key, role, position)
